.fund-settings {
    display: grid;
    grid-template-columns: 1fr 300px;
    gap: 30px;
    margin-top: 20px;
}

.fund-list {
    max-height: 600px;
    overflow-y: auto;
    border: 1px solid #e2e8f0;
    border-radius: 8px;
}

.fund-item {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr 1fr 60px;
    gap: 15px;
    padding: 15px;
    border-bottom: 1px solid #e2e8f0;
    align-items: center;
}

.fund-item:hover {
    background: #f8f9ff;
}

.fund-item input,
.fund-item select {
    padding: 8px;
    border: 1px solid #d1d5db;
    border-radius: 6px;
    font-size: 0.9em;
}

.fund-item input:focus,
.fund-item select:focus {
    outline: none;
    border-color: #667eea;
    box-shadow: 0 0 0 3px rgba(102, 126, 234, 0.1);
}

.add-fund-form {
    background: #f8f9ff;
    padding: 20px;
    border-radius: 8px;
    border: 1px solid #e2e8f0;
}

.form-group {
    margin-bottom: 15px;
}

.form-group label {
    display: block;
    margin-bottom: 5px;
    font-weight: 600;
    color: #374151;
}

.form-group input,
.form-group select {
    width: 100%;
    padding: 10px;
    border: 1px solid #d1d5db;
    border-radius: 6px;
    font-size: 0.9em;
}

.btn {
    padding: 10px 20px;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    font-size: 0.9em;
    transition: all 0.3s;
}

.btn-primary {
    background: #667eea;
    color: white;
}

.btn-primary:hover {
    background: #5a67d8;
}

.btn-danger {
    background: #ef4444;
    color: white;
}

.btn-danger:hover {
    background: #dc2626;
}

.results-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(400px, 1fr));
    gap: 30px;
    margin-top: 20px;
}

.product-card {
    background: white;
    border-radius: 12px;
    padding: 25px;
    box-shadow: 0 5px 15px rgba(0, 0, 0, 0.08);
    border: 1px solid #e2e8f0;
}

.product-card h3 {
    color: #333;
    margin-bottom: 20px;
    font-size: 1.3em;
    text-align: center;
    padding-bottom: 10px;
    border-bottom: 2px solid #667eea;
}

.style-item {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 10px 0;
    border-bottom: 1px solid #f1f5f9;
}

.style-item:last-child {
    border-bottom: none;
}

.style-name {
    font-weight: 600;
    color: #374151;
}

.style-amount {
    color: #667eea;
    font-weight: 600;
}

.style-percentage {
    color: #16a34a;
    font-weight: 600;
}

.chart-container {
    position: relative;
    height: 300px;
    margin-top: 20px;
}

.summary-stats {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 20px;
    margin-top: 20px;
}

.stat-card {
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    color: white;
    padding: 20px;
    border-radius: 10px;
    text-align: center;
}

.stat-card h4 {
    font-size: 0.9em;
    margin-bottom: 10px;
    opacity: 0.9;
}

.stat-card .value {
    font-size: 2em;
    font-weight: 700;
}

.matrix-section {
    margin-top: 30px;
}

.matrix-controls {
    display: flex;
    gap: 20px;
    margin-bottom: 20px;
    align-items: center;
}

.filter-section {
    flex: 1;
    background: #f8f9ff;
    padding: 15px;
    border-radius: 8px;
    border: 1px solid #e2e8f0;
}

