.filter-section h4 {
    margin-bottom: 10px;
    color: #374151;
}

.filter-controls {
    display: flex;
    gap: 10px;
    margin-bottom: 15px;
}

.filter-btn {
    padding: 6px 12px;
    background: #667eea;
    color: white;
    border: none;
    border-radius: 4px;
    font-size: 0.8em;
    cursor: pointer;
    transition: background 0.3s;
}

.filter-btn:hover {
    background: #5a67d8;
}

.filter-btn.secondary {
    background: #6b7280;
}

.filter-btn.secondary:hover {
    background: #4b5563;
}

.filter-checkboxes {
    display: flex;
    flex-wrap: wrap;
    gap: 15px;
}

.filter-checkbox {
    display: flex;
    align-items: center;
    gap: 5px;
}

.filter-checkbox input {
    margin: 0;
}

.filter-checkbox label {
    font-size: 0.9em;
    color: #374151;
    cursor: pointer;
}

.toggle-section {
    background: #f8f9ff;
    padding: 15px;
    border-radius: 8px;
    border: 1px solid #e2e8f0;
    text-align: center;
}

.toggle-section h4 {
    margin-bottom: 10px;
    color: #374151;
}

.toggle-buttons {
    display: flex;
    border-radius: 6px;
    overflow: hidden;
    border: 1px solid #d1d5db;
}

.toggle-btn {
    flex: 1;
    padding: 8px 16px;
    background: white;
    border: none;
    cursor: pointer;
    font-size: 0.9em;
    transition: all 0.3s;
}

.toggle-btn.active {
    background: #667eea;
    color: white;
}

.matrix-table {
    width: 100%;
    border-collapse: collapse;
    background: white;
    border-radius: 8px;
    overflow: hidden;
    box-shadow: 0 5px 15px rgba(0, 0, 0, 0.08);
}

.matrix-table th {
    background: #667eea;
    color: white;
    padding: 12px;
    text-align: center;
    font-weight: 600;
    font-size: 0.9em;
}

.matrix-table td {
    padding: 10px;
    text-align: center;
    border-bottom: 1px solid #e2e8f0;
    font-size: 0.9em;
}

.matrix-table tr:hover {
    background: #f8f9ff;
}

.matrix-table .product-name {
    background: #f8f9ff;
    font-weight: 600;
    color: #374151;
    text-align: left;
    padding-left: 15px;
}

.matrix-table .amount-cell {
    color: #667eea;
    font-weight: 600;
}

.matrix-table .percentage-cell {
    color: #16a34a;
    font-weight: 600;
}

.matrix-table .zero-cell {
    color: #9ca3af;
    font-style: italic;
}

.table-container {
    overflow-x: auto;
    margin-top: 20px;
}

.data-table {
    width: 100%;
    border-collapse: collapse;
    background: white;
    border-radius: 8px;
    overflow: hidden;
    box-shadow: 0 5px 15px rgba(0, 0, 0, 0.08);
}

.data-table th {
    background: #667eea;
    color: white;
    padding: 15px;
    text-align: left;
    font-weight: 600;
}

.data-table td {
    padding: 12px 15px;
    border-bottom: 1px solid #e2e8f0;
}

.data-table tr:hover {
    background: #f8f9ff;
}

.loading {
    display: none;
    text-align: center;
    padding: 20px;
    color: #667eea;
}

.loading.show {
    display: block;
}

.error {
    color: #ef4444;
    background: #fef2f2;
    padding: 10px;
    border-radius: 6px;
    margin-top: 10px;
}

.success {
    color: #16a34a;
    background: #f0fdf4;
    padding: 10px;
    border-radius: 6px;
    margin-top: 10px;
}

@media (max-width: 768px) {
    .fund-settings {
        grid-template-columns: 1fr;
    }

    .fund-item {
        grid-template-columns: 1fr;
        gap: 10px;
    }

    .results-grid {
        grid-template-columns: 1fr;
    }
}

/* 未分类基金样式 */
.unclassified-funds-container {
    background: #fff8f0;
    border: 2px solid #ff6b35;
    border-radius: 12px;
    padding: 20px;
}

.unclassified-fund-item {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr 1fr 80px;
    gap: 15px;
    padding: 15px;
    background: white;
    border-radius: 8px;
    margin-bottom: 10px;
    border: 1px solid #e2e8f0;
    align-items: center;
}

.unclassified-fund-item:hover {
    background: #f8f9ff;
    border-color: #667eea;
}

.unclassified-fund-item .fund-name {
    font-weight: 600;
    color: #333;
    font-size: 0.9em;
}

.unclassified-fund-item .asset-type {
    background: #ff6b35;
    color: white;
    padding: 4px 8px;
    border-radius: 4px;
    font-size: 0.8em;
    text-align: center;
}

.unclassified-fund-item select,
.unclassified-fund-item input {
    padding: 8px;
    border: 1px solid #d1d5db;
    border-radius: 6px;
    font-size: 0.9em;
}

.unclassified-fund-item select:focus,
.unclassified-fund-item input:focus {
    outline: none;
    border-color: #667eea;
    box-shadow: 0 0 0 3px rgba(102, 126, 234, 0.1);
}

.unclassified-fund-header {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr 1fr 80px;
    gap: 15px;
    padding: 10px 15px;
    background: #f8f9ff;
    border-radius: 8px;
    margin-bottom: 15px;
    font-weight: 600;
    color: #667eea;
    font-size: 0.9em;
}

.batch-add-individual {
    background: #10b981;
    color: white;
    border: none;
    border-radius: 4px;
    padding: 6px 12px;
    font-size: 0.8em;
    cursor: pointer;
    transition: background 0.3s;
}

.batch-add-individual:hover {
    background: #059669;
}

