file.content:
/* 资产查询样式 */
.asset-query-section {
    background: linear-gradient(135deg, #f093fb 0%, #f5576c 100%);
    padding: 3px;
    border-radius: 15px;
    margin-bottom: 30px;
}

.asset-query-inner {
    background: white;
    padding: 25px;
    border-radius: 12px;
}

.asset-query-section h2 {
    color: #333;
    margin-bottom: 20px;
    font-size: 1.8em;
    border-bottom: 3px solid #f093fb;
    padding-bottom: 10px;
}

.query-controls {
    display: grid;
    grid-template-columns: 1fr 200px 150px;
    gap: 15px;
    margin-bottom: 20px;
    align-items: end;
}

.search-container {
    position: relative;
}

.search-container label {
    display: block;
    margin-bottom: 5px;
    font-weight: 600;
    color: #374151;
}

.search-input {
    width: 100%;
    padding: 12px 15px;
    border: 2px solid #e2e8f0;
    border-radius: 8px;
    font-size: 1em;
    transition: all 0.3s;
}

.search-input:focus {
    outline: none;
    border-color: #f093fb;
    box-shadow: 0 0 0 3px rgba(240, 147, 251, 0.2);
}

.autocomplete-dropdown {
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    background: white;
    border: 1px solid #e2e8f0;
    border-radius: 8px;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.15);
    max-height: 300px;
    overflow-y: auto;
    z-index: 1000;
    display: none;
}

.autocomplete-dropdown.show {
    display: block;
}

.autocomplete-item {
    padding: 12px 15px;
    cursor: pointer;
    border-bottom: 1px solid #f1f5f9;
    transition: background 0.2s;
}

.autocomplete-item:hover {
    background: #f8f9ff;
}

.autocomplete-item:last-child {
    border-bottom: none;
}

.autocomplete-item .asset-name {
    font-weight: 600;
    color: #333;
    margin-bottom: 3px;
}

.autocomplete-item .asset-code {
    font-size: 0.85em;
    color: #667eea;
    font-family: monospace;
}

.autocomplete-item .asset-tag {
    display: inline-block;
    background: #f093fb;
    color: white;
    padding: 2px 8px;
    border-radius: 4px;
    font-size: 0.75em;
    margin-left: 8px;
}

.tag-select {
    padding: 12px 15px;
    border: 2px solid #e2e8f0;
    border-radius: 8px;
    font-size: 1em;
    cursor: pointer;
}

.tag-select:focus {
    outline: none;
    border-color: #f093fb;
}

.query-btn {
    padding: 12px 24px;
    background: linear-gradient(135deg, #f093fb 0%, #f5576c 100%);
    color: white;
    border: none;
    border-radius: 8px;
    font-size: 1em;
    font-weight: 600;
    cursor: pointer;
    transition: transform 0.2s, box-shadow 0.2s;
}

.query-btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 5px 15px rgba(240, 147, 251, 0.4);
}

.query-results {
    margin-top: 25px;
}

.query-results-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 15px;
}

.query-results-header h3 {
    color: #333;
    font-size: 1.3em;
}

.query-results-summary {
    display: flex;
    gap: 20px;
}

.summary-item {
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    color: white;
    padding: 10px 20px;
    border-radius: 8px;
    text-align: center;
}

.summary-item .label {
    font-size: 0.85em;
    opacity: 0.9;
}

.summary-item .value {
    font-size: 1.3em;
    font-weight: 700;
}

.query-table {
    width: 100%;
    border-collapse: collapse;
    background: white;
    border-radius: 8px;
    overflow: hidden;
    box-shadow: 0 5px 15px rgba(0, 0, 0, 0.08);
}

.query-table th {
    background: linear-gradient(135deg, #f093fb 0%, #f5576c 100%);
    color: white;
    padding: 12px 15px;
    text-align: left;
    font-weight: 600;
}

.query-table td {
    padding: 10px 15px;
    border-bottom: 1px solid #e2e8f0;
}

.query-table tr:hover {
    background: #fef2f8;
}

.query-table .amount-cell {
    color: #667eea;
    font-weight: 600;
    text-align: right;
}

.query-table .percentage-cell {
    color: #16a34a;
    font-weight: 600;
    text-align: right;
}

.query-table .total-row {
    background: #f8f9ff;
    font-weight: 700;
}

.query-table .total-row td {
    border-top: 2px solid #667eea;
}

/* 矩阵表格样式 */
.query-table.matrix-table th {
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    white-space: normal;
    word-break: break-all;
    text-align: center;
    font-size: 0.82em;
    padding: 8px 6px;
    min-width: 80px;
    max-width: 120px;
    line-height: 1.3;
}

.query-table.matrix-table td {
    padding: 8px 10px;
    vertical-align: middle;
}

.query-table.matrix-table td:first-child {
    font-weight: 500;
    white-space: nowrap;
}

.query-table.matrix-table tr:nth-child(even) {
    background: #fafbff;
}

.query-table.matrix-table tr:hover {
    background: #f0f4ff;
}

/* 矩阵表格占比颜色 */
.query-table.matrix-table .percentage-text {
    font-size: 0.85em;
    color: #10b981;
    font-weight: 600;
}

.no-results {
    text-align: center;
    padding: 40px;
    color: #9ca3af;
}

.no-results .icon {
    font-size: 3em;
    margin-bottom: 15px;
}

.asset-tag-badge {
    display: inline-block;
