                '集合资产管理计划',
                '集合资金信托计划',
                '单一资产管理计划',
                '单一资金信托计划',
                '资产管理计划',
                '资金信托计划',
                '信托计划',
                '管理计划'
            ];
            let result = name;
            for (const suffix of suffixes) {
                if (result.endsWith(suffix)) {
                    result = result.slice(0, -suffix.length);
                    break;
                }
            }
            return result.trim();
