function handleClassificationUpload(event) {
    const file = event.target.files[0];
    if (!file) return;

    const loading = document.getElementById('loading');
    const classificationResult = document.getElementById('classificationResult');

    loading.classList.add('show');
    classificationResult.innerHTML = '';

    const reader = new FileReader();
    reader.onload = function (e) {
        try {
            const data = new Uint8Array(e.target.result);
            const workbook = XLSX.read(data, { type: 'array' });

            // 读取基金分类sheet（第一个sheet或名为"基金分类"的sheet）
            let classificationSheet = workbook.Sheets['基金分类'] || workbook.Sheets[workbook.SheetNames[0]];
            const jsonData = XLSX.utils.sheet_to_json(classificationSheet);

            classificationData = jsonData;

            // 处理基金分类数据 - 同时使用外部代码和资产代码建立映射
            fundClassifications = {};
            let successCount = 0;
            let skipCount = 0;

            jsonData.forEach(row => {
                let externalCode = normalizeText(row['外部代码']);
                const assetCode = normalizeText(row['资产代码']);
                const assetClass = normalizeText(row['资产类别（PAS)']);
                const style = normalizeText(row['风格']);
                const equityPosition = parseInt(row['权益仓位']) || 0;

                // 如果外部代码是"0"或空，则忽略
                if (externalCode === '0' || externalCode === '') {
                    externalCode = '';
                }

                if (!style || equityPosition < 0) {
                    skipCount++;
                    return;
                }

                const classificationInfo = {
                    assetClass: assetClass,
                    style: style,
                    equityPosition: equityPosition
                };

                // 同时用外部代码和资产代码建立映射
                if (externalCode) {
                    fundClassifications[externalCode] = classificationInfo;
                    successCount++;
                }
                if (assetCode) {
                    fundClassifications[assetCode] = classificationInfo;
                    if (!externalCode) successCount++; // 只有当没有外部代码时才计数
                }

                if (!externalCode && !assetCode) {
                    skipCount++;
                }
            });

            console.log('基金分类映射详情:', fundClassifications);

            // 读取产品展示顺序sheet
            productOrder = [];
            if (workbook.Sheets['产品展示顺序']) {
                const productOrderData = XLSX.utils.sheet_to_json(workbook.Sheets['产品展示顺序']);
                productOrderData.forEach(row => {
                    const productName = normalizeText(row['产品简称']);
                    if (productName) {
                        productOrder.push(productName);
                    }
                });
                console.log('产品顺序加载完成，数量:', productOrder.length, productOrder);
            }

            // 读取基金风格展示顺序sheet
            styleOrder = [];
            if (workbook.Sheets['基金风格展示顺序']) {
                const styleOrderData = XLSX.utils.sheet_to_json(workbook.Sheets['基金风格展示顺序']);
                styleOrderData.forEach(row => {
                    const style = normalizeText(row['风格']);
                    if (style) {
                        styleOrder.push(style);
                    }
                });
                console.log('风格顺序加载完成，数量:', styleOrder.length, styleOrder);
            }

            // 如果没有从Excel读取到风格顺序，使用默认顺序
            if (styleOrder.length === 0) {
                styleOrder = ['红利', '均衡', '科技成长', '周期', '价值'];
            }

            // 读取资产标签Sheet
            assetTagData = [];
            assetTagMap = {};
            if (workbook.Sheets['资产标签']) {
                assetTagData = XLSX.utils.sheet_to_json(workbook.Sheets['资产标签']);
                assetTagData.forEach(row => {
                    const assetCode = normalizeText(row['资产代码']);
                    if (assetCode) {
                        assetTagMap[assetCode] = {
                            assetName: normalizeText(row['资产简称']),
                            tag: normalizeText(row['标签']),
                            category: normalizeText(row['细分资产类别']),
                            subClass: normalizeText(row['新版资产小类'])
                        };
                    }
                });
                console.log('资产标签加载完成，数量:', assetTagData.length);
            }

            isClassificationLoaded = true;
            loading.classList.remove('show');

            let resultMsg = `✅ 成功加载 ${successCount} 个基金分类`;
            if (skipCount > 0) resultMsg += ` (跳过 ${skipCount} 个无效记录)`;
            if (productOrder.length > 0) resultMsg += `<br>📋 产品顺序: ${productOrder.length} 个`;
            if (styleOrder.length > 0) resultMsg += `<br>🎨 风格顺序: ${styleOrder.join('→')}`;
            if (assetTagData.length > 0) resultMsg += `<br>🏷️ 资产标签: ${assetTagData.length} 个`;

            classificationResult.innerHTML = `<div class="success">${resultMsg}</div>`;

            // 更新标签下拉框
            updateTagSelect();

            console.log('基金分类数据加载完成，数量:', successCount);

            // 如果已经上传了持仓表，重新处理
            if (holdingData.length > 0) {
                processData();
            }
        } catch (error) {
            loading.classList.remove('show');
            classificationResult.innerHTML = `<div class="error">❌ 基金分类表处理失败: ${error.message}</div>`;
            console.error('基金分类表处理失败:', error);
        }
    };
    reader.readAsArrayBuffer(file);
}

