// 计算详细数据（包括产品净资产和调仓信息）
function calculateDetailData() {
    const detailData = [];
    const productNetAssets = {}; // 存储各产品的净资产
    const processedTradeKeys = new Set(); // 记录已处理的交易键

    // 首先计算各产品的净资产
    holdingData.forEach(row => {
        const productName = normalizeText(row['产品简称']);
        const assetName = normalizeText(row['资产简称']);
        const holdingAmount = parseFloat(row['日终市值(元)-产品法估值']) || 0;

        if (!productName || holdingAmount === 0) return;

        if (!productNetAssets[productName]) {
            productNetAssets[productName] = 0;
        }

        // 检查是否为正回购
        const isRepo = assetName && assetName.includes('正回购');

        if (isRepo) {
            // 正回购从净资产中减去
            productNetAssets[productName] -= holdingAmount;
        } else {
            // 其他资产加入净资产
            productNetAssets[productName] += holdingAmount;
        }
    });

    // 然后生成详细数据
    holdingData.forEach(row => {
        const productName = normalizeText(row['产品简称']);
        const assetName = normalizeText(row['资产简称']);
        const holdingAmount = parseFloat(row['日终市值(元)-产品法估值']) || 0;
        const holdingQuantity = parseFloat(row['持仓面额']) || 0;
        const fullPrice = parseFloat(row['日终全价（元）-产品法估值']) || 0;
        const externalCode = normalizeText(row['外部代码']);
        const assetCode = normalizeText(row['资产代码']);

        if (!productName || !assetName || holdingAmount === 0) return;

        // 使用新的匹配键逻辑
        const matchKey = getFundMatchKey(row);
        const classification = fundClassifications[matchKey];
        if (!classification) return;

        // 计算调仓
        let tradeAdjustment = 0;
        let adjustedHolding = holdingAmount;
        let hasTrade = false;

        // 使用外部代码或资产代码构建交易键
        const matchCode = (externalCode && externalCode !== 'nan') ? externalCode : assetCode;
        const tradeKey = matchCode ? `${productName}|${matchCode}` : null;

        if (tradeKey && tradeMap[tradeKey]) {
            processedTradeKeys.add(tradeKey);
            const tradeInfo = tradeMap[tradeKey];
            hasTrade = true;
            console.log(`匹配到交易: ${tradeKey}, 申购=${tradeInfo.purchaseAmount}, 赎回数量=${tradeInfo.redeemQuantity}`);

            // 申购增加持仓
            if (tradeInfo.purchaseAmount > 0) {
                tradeAdjustment += tradeInfo.purchaseAmount;
                adjustedHolding = holdingAmount + tradeInfo.purchaseAmount;
            }

            // 赎回减少持仓
            if (tradeInfo.redeemQuantity > 0) {
                if (fullPrice > 0) {
                    const newQuantity = Math.max(0, holdingQuantity - tradeInfo.redeemQuantity);
                    const newValue = newQuantity * fullPrice;
                    tradeAdjustment = newValue - holdingAmount;
                    adjustedHolding = newValue;
                    console.log(`赎回计算: 原数量=${holdingQuantity}, 赎回=${tradeInfo.redeemQuantity}, 全价=${fullPrice}, 新值=${newValue}`);
                } else {
                    console.log(`赎回计算失败: 全价为0, 持仓=${assetName}`);
                }
            }
        }

        const equityExposure = adjustedHolding * (classification.equityPosition / 100);

        detailData.push({
            productName,
            assetName,
            assetCode: externalCode || assetCode,
            assetClass: classification.assetClass,
            style: classification.style,
            equityPosition: classification.equityPosition,
            holdingAmount,
            tradeAdjustment,
            adjustedHolding,
            equityExposure,
            productNetAsset: productNetAssets[productName],
            hasTrade,
            isNew: false
        });
    });

    // 处理新申购资产（持仓表中没有的）
    console.log('处理新申购资产, tradeMap键数量:', Object.keys(tradeMap).length);
    console.log('已处理的交易键:', Array.from(processedTradeKeys));

    Object.keys(tradeMap).forEach(tradeKey => {
        if (processedTradeKeys.has(tradeKey)) {
            console.log(`跳过已处理: ${tradeKey}`);
            return;
        }

        const tradeInfo = tradeMap[tradeKey];
        if (tradeInfo.purchaseAmount <= 0) {
            console.log(`跳过无申购: ${tradeKey}`);
            return;
        }

        const [productName, assetCode] = tradeKey.split('|');
        const classification = fundClassifications[assetCode];

        if (!classification) {
            console.log(`跳过无分类: ${tradeKey}, assetCode=${assetCode}`);
            return;
        }

        console.log(`添加新申购: ${tradeKey}, 金额=${tradeInfo.purchaseAmount/10000}万`);

        const adjustedHolding = tradeInfo.purchaseAmount;
        const equityExposure = adjustedHolding * (classification.equityPosition / 100);

        detailData.push({
            productName,
            assetName: tradeInfo.assetName,
            assetCode: assetCode,
            assetClass: classification.assetClass,
            style: classification.style,
            equityPosition: classification.equityPosition,
            holdingAmount: 0,
            tradeAdjustment: tradeInfo.purchaseAmount,
            adjustedHolding,
            equityExposure,
            productNetAsset: productNetAssets[productName] || 0,
            hasTrade: true,
            isNew: true
        });
    });

    console.log('calculateDetailData完成, 总记录数:', detailData.length);
    const withTrade = detailData.filter(d => d.hasTrade);
    console.log('有交易调整的记录数:', withTrade.length);

    return detailData;
}

