// ==================== 资产查询功能 ====================

// 构建资产列表（用于自动补全）
function buildAssetsList() {
    const assetMap = new Map(); // 用于去重

    holdingData.forEach(row => {
        const assetName = normalizeText(row['资产简称']);
        const externalCode = normalizeText(row['外部代码']);
        const assetCode = normalizeText(row['资产代码']);

        if (!assetName) return;

        // 使用资产代码或外部代码作为唯一键
        const key = (externalCode && externalCode !== 'nan') ? externalCode : assetCode;
        if (!key) return;

        if (!assetMap.has(key)) {
            // 获取标签信息
            const tagInfo = assetTagMap[assetCode] || {};

            assetMap.set(key, {
                assetName: assetName,
                externalCode: externalCode,
                assetCode: assetCode,
                matchKey: key,
                tag: tagInfo.tag || '',
                category: tagInfo.category || ''
            });
        }
    });

    allAssetsList = Array.from(assetMap.values());
    console.log('资产列表构建完成，数量:', allAssetsList.length);
}

// 更新标签下拉框
function updateTagSelect() {
    const tagSelect = document.getElementById('tagSelect');
    if (!tagSelect) return;

    // 获取所有唯一标签
    const tags = new Set();
    assetTagData.forEach(row => {
        const tag = normalizeText(row['标签']);
        if (tag) tags.add(tag);
    });

    // 清空并重建选项
    tagSelect.innerHTML = '<option value="">-- 选择标签 --</option>';
    Array.from(tags).sort().forEach(tag => {
        const option = document.createElement('option');
        option.value = tag;
        option.textContent = tag;
        tagSelect.appendChild(option);
    });

    console.log('标签选项更新完成，数量:', tags.size);
}

// 已选择的资产列表
let selectedAssets = [];

// 解析搜索文本，支持多种分隔符
function parseSearchText(text) {
    // 支持的分隔符：空格、逗号、分号、换行、制表符、中文逗号、中文分号
    const separators = /[\s,;，；\t\n]+/;
    return text.split(separators).map(s => s.trim()).filter(s => s.length > 0);
}

